//! Cargo-driven `deskmon.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is deskmon-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMainCRTStartup@12", Some(0x755b0000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMainCRTStartup", Some(0x7ff31000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMainCRTStartup", Some(0x7ff31000000u64)),
        o => panic!("deskmon-cargo: unsupported arch {o}"),
    };

    let static_libs: &[&str] = match arch.as_str() {
        "x86" => &["sdk/lib/uuid/libuuid.a", "sdk/lib/crt/CMakeFiles/oldnames.dir/oldnames.a"],
        "x86_64" => &["sdk/lib/uuid/libuuid.a", "sdk/lib/crt/CMakeFiles/oldnames.dir/oldnames.a"],
        "aarch64" => &["sdk/lib/uuid/libuuid.a", "sdk/lib/crt/CMakeFiles/oldnames.dir/oldnames.a"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("deskmon-rust")
        .resource_from_rc("dll/shellext/deskmon/deskmon.rc", "deskmon_res")
        .spec2def("dll/shellext/deskmon/deskmon.spec", "deskmon.dll")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("win32ss/gdi/gdi32/gdi32.spec", "gdi32.dll", "gdi32")
        .import_lib("dll/win32/comctl32/comctl32.spec", "comctl32.dll", "comctl32")
        .import_lib("dll/win32/ole32/ole32.spec", "ole32.dll", "ole32")
        .import_lib("dll/win32/setupapi/setupapi.spec", "setupapi.dll", "setupapi")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // cmake-built static libraries, reused until each has a cargo home.
        .static_libs(static_libs)
        .msvcrtex_crt(MsvcrtexKind::Dll)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
